package com.aai.app

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/** Small transparent ARIS cut-out extracted from the supplied character model sheet. */
internal object CharacterArtwork {
    private const val WEBP_BASE64 = ""
    @Volatile private var cached: Bitmap? = null
    fun bitmap(context: Context): Bitmap? {
        cached?.let { return it }
        return runCatching {
            val bytes = Base64.decode(WEBP_BASE64, Base64.DEFAULT)
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
        }.getOrNull()?.also { cached = it }
    }
}
